            io(["“Fully fixed” anyway", "”Helt åtgärdat” ändå"], ["That afternoon a board member tells a reporter the app is “fully fixed”. Your careful answer is now contradicted in public by your own board.", "Samma eftermiddag säger en styrelseledamot till en reporter att appen är ”helt åtgärdad”. Ert noggranna svar motsägs nu offentligt av er egen styrelse."], ["A board member told the press the app is “fully fixed”.", "En styrelseledamot sade till pressen att appen är ”helt åtgärdad”."], { meters: { media: 1 } }),
            io(["Evidence still in progress", "Beläggen pågår fortfarande"], ["A board member asks to see the evidence. Some of the testing behind “safer” is not finished, and the minutes record that too.", "En ledamot vill se beläggen. En del av testerna bakom ”säkrare” är inte klara, och det protokollförs också."], ["Parts of the evidence behind “safer” are still in progress.", "Delar av beläggen bakom ”säkrare” pågår fortfarande."])
