            io(["Researchers walk away", "Forskarna vänder ryggen till"], ["Several researchers announce that they will publish flaws in your products directly from now on, rather than report them to you.", "Flera forskare meddelar att de hädanefter publicerar brister i era produkter direkt, i stället för att rapportera dem till er."], ["Several researchers say they will publish your flaws directly.", "Flera forskare säger att de publicerar era brister direkt."], { reopen: true, meters: { media: 1 } }),
            io(["A list of dates", "En lista med datum"], ["She posts a short follow-up: the date of every message between you, nothing more. Readers can draw their own conclusions.", "Hon lägger upp en kort uppföljning: datumet för varje meddelande mellan er, inget mer. Läsarna får dra sina egna slutsatser."], ["The researcher has published the dates of every exchange.", "Forskaren har publicerat datumen för varje kontakt."])
